@Service
@RequiredArgsConstructor
public class InvitationService {

    private final InvitationRepository invitationRepository;
    private final MemberRepository memberRepository;
    private final EmailSender emailSender;

    public void inviteMember(String email) {
        // 1. null 및 공백 검증
        if (email == null || email.trim().isEmpty()) {
            throw new IllegalArgumentException("이메일은 필수 입력값입니다.");
        }

        // 2. 이메일 형식 검증 (정규식)
        String trimmedEmail = email.trim();
        if (!isValidEmailFormat(trimmedEmail)) {
            throw new IllegalArgumentException("잘못된 이메일 형식입니다.");
        }

        // 3. 이미 가입된 회원인지 검증 (소문자 기준 비교를 위해 변환 고려 가능)
        if (memberRepository.existsByEmail(trimmedEmail)) {
            throw new IllegalStateException("이미 가입된 회원입니다.");
        }

        // 4. 이미 초대된 이메일인지 검증 (중복 초대)
        if (invitationRepository.existsByEmail(trimmedEmail)) {
            throw new IllegalStateException("이미 초대된 이메일입니다.");
        }

        // 5. 초대 메일 발송 및 저장
        invitationRepository.save(new Invitation(trimmedEmail));
        emailSender.send(trimmedEmail);
    }

    private boolean isValidEmailFormat(String email) {
        String emailRegex = "^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$";
        return email.matches(emailRegex);
    }
}
```

