가장 범용적으로 사용되는 **Spring Jasypt** 또는 **Java 기본 `javax.crypto.Cipher` (AES)** 방식을 가정하여, DB에서 암호화된 값을 가져와 복호화한 후 원본 값과 일치하는지 검증하는 JUnit 5 테스트 코드를 작성해 드립니다.

### 1. 테스트 코드 (Java + JUnit 5 + AES)

실제 프로젝트에서 사용하는 암호화 유틸리티 클래스(`AesUtil` 또는 `StandardPBEStringEncryptor` 등)가 있다고 가정하고, 순수 Java AES 방식으로 구현한 테스트 예시입니다.

```java
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

import static org.assertj.core.api.Assertions.assertThat;

class DecryptionTest {

    // 실무에서는 application.yml 또는 환경 변수에서 주입받아야 합니다.
    private static final String ALGORITHM = "AES";
    private static final String SECRET_KEY = "MySuperSecretKey!"; // 16자리 키 (AES-128 기준)

    @Test
    @DisplayName("DB에 암호화된 주민등록번호 복호화 및 검증 테스트")
    void decryptAndVerifyTest() throws Exception {
        // given
        String originalRrn = "000423-4092706";

        // [상황 가정] DB에 이미 암호화되어 저장되어 있는 값
        String encryptedDataInDb = encrypt(originalRrn);
        System.out.println("DB에 저장된 암호화 데이터: " + encryptedDataInDb);

        // when
        // 1. DB에서 값을 조회했다고 가정
        String fetchedEncryptedData = encryptedDataInDb;

        // 2. 복호화 실행
        String decryptedRrn = decrypt(fetchedEncryptedData);
        System.out.println("복호화된 데이터: " + decryptedRrn);

        // then
        // 3. 검증
        assertThat(decryptedRrn).isEqualTo(originalRrn);
    }

    // --- 암호화 헬퍼 메서드 (테스트용) ---
    private String encrypt(String value) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(SECRET_KEY.getBytes(StandardCharsets.UTF_8), ALGORITHM);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);
        byte[] encryptedBytes = cipher.doFinal(value.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }

    // --- 복호화 메서드 (실제 검증 대상) ---
    private String decrypt(String encryptedValue) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(SECRET_KEY.getBytes(StandardCharsets.UTF_8), ALGORITHM);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, keySpec);
        byte[] decodedBytes = Base64.getDecoder().decode(encryptedValue);
        byte[] decryptedBytes = cipher.doFinal(decodedBytes);
        return new String(decryptedBytes, StandardCharsets.UTF_8);
    }
}
```

