import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class SpringDecryptionTest {

    @Autowired
    private EncryptComponent encryptComponent; // 암복호화를 담당하는 스프링 빈

    @Test
    @DisplayName("Spring 빈을 이용한 DB 데이터 복호화 검증")
    void springDecryptTest() {
        // given
        String originalRrn = "000423-4092706";
        String encryptedValueFromDb = encryptComponent.encrypt(originalRrn); // DB 저장 값 가정

        // when
