import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class ResidentNumberDecryptionTest {

    // 실제 프로젝트에서 사용하는 암/복호화 컴포넌트 (Service 또는 Util)
    @Autowired
    private EncryptorComponent encryptorComponent;

    // 실제 DB Repository (주민번호가 암호화되어 저장되어 있다고 가정)
    @Autowired
    private UserRepository userRepository;

    @Test
    @DisplayName("DB에 암호화된 주민번호를 복호화하여 원본 값과 일치하는지 검증")
    void decryptAndVerifyResidentNumber() {
        // given: 테스트를 위한 원본 주민번호와 사용자 ID
        String originalRrn = "990101-1234567";
        Long userId = 1L;

        // [참고] 만약 DB에 데이터가 미리 들어가있지 않다면 테스트용 데이터를 먼저 넣어줍니다.
        // String encryptedRrn = encryptorComponent.encrypt(originalRrn);
        // userRepository.save(new User(userId, encryptedRrn));

        // when: DB에서 암호화된 주민번호 조회
        String encryptedRrnFromDb = userRepository.findResidentNumberById(userId);

        // then 1: DB의 값이 암호화되어 있는지 확인 (원본과 다른가?)
        assertThat(encryptedRrnFromDb).isNotEqualTo(originalRrn);

        // when: 복호화 수행
        String decryptedRrn = encryptorComponent.decrypt(encryptedRrnFromDb);

        // then 2: 복호화된 값이 원본 주민번호와 일치하는지 검증
        assertThat(decryptedRrn).isEqualTo(originalRrn);

        // then 3: 주민번호 형식(regex) 검증 추가 (선택사항)
        assertThat(decryptedRrn).matches("^\\d{6}-[1-4]\\d{6}$");
    }
}
```

