### 1. JavaScript / TypeScript 코드

```javascript
function isValidLuhn(cardNumber) {
    // 1. 공백 및 하이픈(-) 제거
    const sanitized = cardNumber.replace(/[\s-]/g, '');

    // 숫자가 아니거나 너무 짧은 경우 false 반환
    if (!/^\d+$/.test(sanitized) || sanitized.length < 2) {
        return false;
    }

    let sum = 0;
    let shouldDouble = false;

    // 2. 우측(마지막 자리)부터 좌측으로 순회
    for (let i = sanitized.length - 1; i >= 0; i--) {
        let digit = parseInt(sanitized.charAt(i), 10);

        if (shouldDouble) {
            digit *= 2;
            // 두 배 한 값이 10 이상이면 각 자리의 숫자를 더함 (예: 14 -> 1 + 4 = 5)
            if (digit > 9) {
                digit -= 9;
            }
        }

        sum += digit;
        shouldDouble = !shouldDouble; // 홀/짝 자리 전환
    }

    // 3. 총합이 10으로 나누어 떨어지면 유효한 번호
    return sum % 10 === 0;
}

// 테스트
const testCard = "6289-7454-1782-3183";
console.log(`카드 번호 ${testCard} 유효성 검사 결과:`, isValidLuhn(testCard));
```

