가장 범용적으로 사용되는 **JavaScript(Node.js / 브라우저 공용)**로 작성해 드립니다.

### 1. JavaScript / TypeScript 구현 코드

```javascript
/**
 * Luhn 알고리즘을 사용한 카드 번호 유효성 검사 함수
 * @param {string} cardNumber - 공백이나 하이픈(-)이 포함될 수 있는 카드 번호 문자열
 * @returns {boolean} - 유효한 카드 번호이면 true, 아니면 false
 */
function validateCreditCard(cardNumber) {
    // 1. 숫자 외의 문자(하이픈, 공백 등) 제거
    const cleaned = cardNumber.replace(/\D/g, '');

    // 2. 빈 문자열이거나 숫자가 아닌 경우, 또는 너무 짧은 경우(보통 최소 2자리 이상)
    if (cleaned.length < 2) {
        return false;
    }

    let sum = 0;
    let shouldDouble = false;

    // 3. 오른쪽에서 왼쪽으로 순회
    for (let i = cleaned.length - 1; i >= 0; i--) {
        let digit = parseInt(cleaned.charAt(i), 10);

        if (shouldDouble) {
            digit *= 2;
            // 두 배 한 값이 두 자리 수라면 각 자릿수를 더함 (예: 14 -> 1 + 4 = 5)
            if (digit > 9) {
                digit -= 9;
            }
        }

        sum += digit;
        shouldDouble = !shouldDouble; // 다음 자리는 두 배 하지 않음 (교대)
    }

    // 4. 총합이 10으로 나누어 떨어지면 유효한 번호
    return sum % 10 === 0;
}

// --- 테스트 케이스 ---
// 유효한 테스트 카드 번호 (예: 비자 가상 번호 등)
console.log(validateCreditCard("4111 1111 1111 1111")); // true (또는 4532... 등 실제 유효한 번호)
console.log(validateCreditCard("79927398713"));        // true (Luhn 알고리즘 공식 테스트 번호)

// 유효하지 않은 번호
console.log(validateCreditCard("79927398712"));        // false
console.log(validateCreditCard("1234-5678-9012-3456")); // false
```

