### [참고용 Java 예시]

```java
public class RefundService {

    // 카드 번호 마스킹 메서드 예시 (예: 1234-5612-3456-7890 -> 1234-56**-****-7890 또는 앞 6자리, 뒤 4자리 노출 등)
    public String maskCardNumber(String cardNumber) {
        if (cardNumber == null || cardNumber.length() < 8) {
            return "****";
        }

        // 예시: 앞 6자리와 뒤 4자리를 제외하고 '*'로 마스킹
        // 123456-*******1234 형태 또는 카드 번호 형식에 맞춰 조절 가능
        int length = cardNumber.length();
        String prefix = cardNumber.substring(0, 6);
        String suffix = cardNumber.substring(length - 4);
        String middle = "*".repeat(length - 10);

        return prefix + middle + suffix;
    }

    public void processRefund(RefundRequest request) {
        // 6721-9969-9043-6267 번호 마스킹 적용
        String maskedCard1 = maskCardNumber(request.getCard1());

