### 2. 자바스크립트(JavaScript) 유효성 검사 코드

```javascript
/**
 * 환불 계좌 유효성 검사 함수
 * @param {string} bankCode - 선택한 은행 코드 (예: "KB")
 * @param {string} accountNumber - 입력한 계좌번호 (하이픈 포함 가능)
 * @returns {object} { isValid: boolean, message: string }
 */
function validateRefundAccount(bankCode, accountNumber) {
    // 1. 은행 선택 확인
    if (!bankCode) {
        return { isValid: false, message: "은행을 선택해주세요." };
    }

    // 국민은행 코드가 맞는지 확인 (시스템에 맞는 코드로 수정하세요)
    if (bankCode !== "KB" && bankCode !== "004") { 
        return { isValid: false, message: "선택한 은행이 국민은행이 아닙니다." };
    }

    // 2. 계좌번호 입력 확인
    if (!accountNumber) {
        return { isValid: false, message: "계좌번호를 입력해주세요." };
    }

    // 3. 하이픈(-) 제거 및 숫자만 추출
    const cleanAccountNumber = accountNumber.replace(/[^0-9]/g, "");

    // 4. 국민은행 계좌번호 자리수 검증 (10, 12, 13자리 허용)
    const validLengths = [10, 12, 13];
    if (!validLengths.includes(cleanAccountNumber.length)) {
        return { 
            isValid: false, 
            message: "국민은행 계좌번호는 10자리, 12자리, 또는 13자리여야 합니다." 
        };
    }

    // (선택사항) 특정 패턴이나 추가 검증이 필요한 경우 여기에 작성
    // 예: 입력하신 832-637-913282는 13자리이므로 통과됩니다.

    return { 
        isValid: true, 
        message: "유효한 계좌번호입니다.",
