### 1. 주민등록번호 & 전화번호 포맷팅 함수 (JavaScript)

입력값에 숫자가 들어올 때 자동으로 형식을 맞춰주는 유틸리티 함수입니다.

```javascript
// 1. 주민등록번호 포맷팅 (000000-0000000)
function formatRRN(value) {
    // 숫자 외의 문자는 모두 제거
    const numbers = value.replace(/[^0-9]/g, '');

    if (numbers.length <= 6) {
        return numbers;
    }
    // 6자리 초과 시 하이픈(-) 추가
    return numbers.slice(0, 6) + '-' + numbers.slice(6, 13);
}

// 2. 전화번호 포맷팅 (010-0000-0000 또는 일반 전화번호)
function formatPhone(value) {
    const numbers = value.replace(/[^0-9]/g, '');

    if (numbers.length < 4) {
        return numbers;
    } else if (numbers.length < 7) {
        return numbers.slice(0, 3) + '-' + numbers.slice(3);
    } else if (numbers.length < 11) {
        // 서울 지역번호(02) 등 10자리 번호 대응
        if (numbers.startsWith('02')) {
            return numbers.slice(0, 2) + '-' + numbers.slice(2, 5) + '-' + numbers.slice(5, 10);
        }
        return numbers.slice(0, 3) + '-' + numbers.slice(3, 6) + '-' + numbers.slice(6, 10);
    } else {
        // 11자리 휴대폰 번호
        return numbers.slice(0, 3) + '-' + numbers.slice(3, 7) + '-' + numbers.slice(7, 11);
    }
}
```

