### 1. JavaScript 유효성 검사 코드

내국인 번호와 외국인 번호는 **성별/국적을 나타내는 7번째 자리의 숫자**로 구분됩니다.
*   **내국인 (7번째 자리):** `1, 2, 3, 4` (1900년대 출생 남/여, 2000년대 출생 남/여)
*   **외국인 (7번째 자리):** `5, 6, 7, 8` (1900년대 등록 남/여, 2000년대 등록 남/여)

```javascript
function validateRegistrationNumber(regNo) {
    // 1. 기본 형식 검증 (생년월일6자리 - 성별구분포함뒷자리7자리)
    // 예시로 주신 011230-3846098, 010517-8909176 모두 통과합니다.
    const regNoRegex = /^\d{6}-[1-8]\d{6}$/;

    if (!regNoRegex.test(regNo)) {
        return { isValid: false, message: "형식이 올바르지 않습니다. (예: 000000-0000000)" };
    }

    // 2. 내국인/외국인 구분 및 추가 검증
    const genderDigit = regNo.charAt(7); // 7번째 자리 문자 추출 (- 제외하고 7번째, 혹은 전체에서 8번째)
    // * 주의: 011230-3846098 에서 '-'를 포함하면 index 7은 '-'입니다. 
    // 보통 '-'를 제거하고 체크하거나, 아래처럼 인덱스를 잡습니다.

    const cleanNo = regNo.replace('-', '');
    const seventhChar = cleanNo.charAt(6); // 0부터 시작하므로 7번째 자리는 index 6

    if (['1', '2', '3', '4'].includes(seventhChar)) {
        // 내국인 번호 로직
        // 필요시 주민등록번호 공식 검증 알고리즘 추가 가능
        return { isValid: true, type: 'LOCAL', message: "유효한 내국인 번호입니다." };

    } else if (['5', '6', '7', '8'].includes(seventhChar)) {
        // 외국인 번호 로직
        // 외국인등록번호 유효성 검증 알고리즘 추가 가능
        return { isValid: true, type: 'FOREIGNER', message: "유효한 외국인 번호입니다." };

    } else {
        return { isValid: false, message: "유효하지 않은 성별/국적 구분 번호입니다." };
    }
}

// --- 테스트 ---
console.log(validateRegistrationNumber("011230-3846098")); // 내국인 (7번째 자리가 3) -> {isValid: true, type: 'LOCAL'}
console.log(validateRegistrationNumber("010517-8909176")); // 외국인 (7번째 자리가 8) -> {isValid: true, type: 'FOREIGNER'}
console.log(validateRegistrationNumber("011230-9999999")); // 실패 (9는 올바르지 않음)
```

