### 2. 통합 유효성 검사 함수 (인사관리 시스템 적용 예시)

사용자가 선택한 국적(내국인/외국인)에 따라 알맞은 필드를 검증하는 함수입니다.

```javascript
/**
 * 인사관리 시스템 등록/수정 시 호출하는 유효성 검사 함수
 * @param {string} userType - 'DOMESTIC' (내국인) 또는 'FOREIGNER' (외국인)
 * @param {string} idNumber - 입력된 번호 (011230-3846098 또는 010517-8909176)
 */
function validateIdNumber(userType, idNumber) {
  if (!idNumber) {
    return { isValid: false, message: "번호를 입력해주세요." };
  }

  if (userType === 'DOMESTIC') {
    // 내국인 검사
    if (!isValidResidentNumber(idNumber)) {
      return { isValid: false, message: "올바른 주민등록번호 형식이 아닙니다." };
    }
  } else if (userType === 'FOREIGNER') {
    // 외국인 검사
    if (!isValidForeignerNumber(idNumber)) {
      return { isValid: false, message: "올바른 외국인등록번호 형식이 아닙니다." };
    }
  } else {
    return { isValid: false, message: "내/외국인 구분값이 올바르지 않습니다." };
  }

  return { isValid: true, message: "유효한 번호입니다." };
}
```

